+void TaskToolsTest::testServiceFromLaunchScope()
+{
+    QFETCH(QString, launchDesktopName);
+    QFETCH(QString, resultStorageId);
+
+    // Start a process the way KIO launches applications, in a systemd scope named after the desktop file.
+    const QString unit = u"app-%1-%2.scope"_s.arg(QString(launchDesktopName).replace(u'-', u"\\x2d"_s), QUuid::createUuid().toString(QUuid::Id128));
+    QProcess process;
+    process.start(u"systemd-run"_s, {u"--user"_s, u"--scope"_s, u"--quiet"_s, u"--unit="_s + unit, u"sleep"_s, u"60"_s});
+    if (!process.waitForStarted()) {
+        QSKIP("systemd-run is not available");
+    }
+
+    const auto isInScope = [&process, &unit] {
+        QFile cgroupFile(u"/proc/%1/cgroup"_s.arg(process.processId()));
+        return cgroupFile.open(QIODevice::ReadOnly) && cgroupFile.readAll().trimmed().endsWith(u"/%1"_s.arg(unit).toUtf8());
+    };
+    QTRY_VERIFY_WITH_TIMEOUT(process.state() != QProcess::Running || isInScope(), 5000);
+    if (process.state() != QProcess::Running) {
+        QSKIP("systemd user instance is not available");
+    }
+
+    const auto service = serviceFromMetadata(u"org.kde.dolphin"_s, process.processId(), QString(), QString());
+
+    process.kill();
+    process.waitForFinished();
+
+    QCOMPARE(service->storageId(), resultStorageId);
+}
+
+void TaskToolsTest::testServiceFromLaunchScope_data()
+{
+    QTest::addColumn<QString>("launchDesktopName");
+    QTest::addColumn<QString>("resultStorageId");
+
+    QTest::addRow("same desktop file") << "org.kde.dolphin" << "org.kde.dolphin.desktop";
+    QTest::addRow("other desktop file, same executable") << "dolphin-home" << "dolphin-home.desktop";
+    QTest::addRow("other executable") << "org.kde.konversation" << "org.kde.dolphin.desktop";
+    QTest::addRow("other StartupWMClass") << "dolphin-webapp" << "org.kde.dolphin.desktop";
+}
